// ttsTrim.ts — the voice stops where the text stops (ZAD_PLAN ١.١٤، 2026-10-19).
//
// The owner heard Zad's voice notes end in noise and an English «speech generated by …» that no
// text of ours contains: Gemini TTS sometimes keeps going after the words it was given. The prompt
// cannot simply be reshaped — its closing «Now generate the speech audio» is what keeps the model
// from refusing with 400 «tried to generate text» (zadVoice.ts) — so the guard is on the audio:
// when a clip runs far longer than its text could take, it is cut at the first pause after the
// expected length, with a short fade so the cut does not click. A clip of normal length is
// returned untouched.

/** Gemini TTS and Azure's raw format: 24 kHz, 16-bit little-endian, mono. */
export const TTS_SAMPLE_RATE = 24_000;

const FRAME_MS = 20;
const PAUSE_MS = 350;
const FADE_MS = 40;

/**
 * How long the text could take at a slow, emotional delivery (sighs and laughs included):
 * two words a second plus a second of breath. Generous on purpose — only a runaway goes past it.
 */
export function expectedSpeechSeconds(text: string): number {
  const words = text.trim().split(/\s+/).filter((w) => /[\p{L}\p{N}]/u.test(w)).length;
  return words / 2 + 1;
}

/** The longest a clip of [text] may run before it counts as a runaway. */
export function runawayLimitSeconds(text: string): number {
  return expectedSpeechSeconds(text) * 1.3 + 1;
}

function frameRms(samples: Int16Array, start: number, length: number): number {
  let sum = 0;
  const end = Math.min(samples.length, start + length);
  for (let i = start; i < end; i++) sum += samples[i] * samples[i];
  return end > start ? Math.sqrt(sum / (end - start)) : 0;
}

/**
 * The clip, cut at the first pause after the text's expected length when it runs past
 * [runawayLimitSeconds]; untouched otherwise. With no pause to cut at, it ends at the limit.
 */
export function trimRunawaySpeech(pcm: Uint8Array<ArrayBuffer>, text: string, sampleRate = TTS_SAMPLE_RATE): Uint8Array<ArrayBuffer> {
  const samples = new Int16Array(pcm.buffer, pcm.byteOffset, Math.floor(pcm.byteLength / 2));
  const seconds = samples.length / sampleRate;
  if (seconds <= runawayLimitSeconds(text)) return pcm;

  const frame = Math.max(1, Math.round((sampleRate * FRAME_MS) / 1000));
  const rms: number[] = [];
  for (let i = 0; i < samples.length; i += frame) rms.push(frameRms(samples, i, frame));
  // Quiet = under a tenth of the loud frames' level (90th percentile), so it follows the voice.
  const loud = [...rms].sort((a, b) => a - b)[Math.floor(rms.length * 0.9)] ?? 0;
  const quiet = Math.max(150, loud * 0.1);
  const pauseFrames = Math.ceil(PAUSE_MS / FRAME_MS);
  // Real speech is quicker than the generous estimate, so the search starts at half of it; a
  // pause that began just before counts from its own start.
  const fromFrame = Math.floor((expectedSpeechSeconds(text) * 0.5 * 1000) / FRAME_MS);
  const limitFrame = Math.floor((runawayLimitSeconds(text) * 1000) / FRAME_MS);

  let cutFrame = limitFrame;
  let run = 0;
  for (let f = fromFrame - 1; f >= 0 && rms[f] < quiet; f--) run++;
  for (let f = fromFrame; f < rms.length; f++) {
    run = rms[f] < quiet ? run + 1 : 0;
    if (run >= pauseFrames) {
      cutFrame = f - run + 1;
      break;
    }
  }
  cutFrame = Math.min(cutFrame, limitFrame);
  const cutSample = Math.min(samples.length, cutFrame * frame);

  const out = new Int16Array(cutSample);
  out.set(samples.subarray(0, cutSample));
  const fade = Math.min(cutSample, Math.round((sampleRate * FADE_MS) / 1000));
  for (let i = 0; i < fade; i++) {
    const idx = cutSample - fade + i;
    out[idx] = Math.round(out[idx] * (1 - (i + 1) / fade));
  }
  return new Uint8Array(out.buffer);
}
